    unit = opeu_battle_element_unit(ds, event, element);
    call0(ds, event, 0x048a4u);
    call2(ds, event, 0x2a14au, ACTIVE_SIDE, 0);
    {
      uint16_t text = 0xbb28u;
      event(ds, 0x04c84u, &text, 1);
    }
    if (!opeu_battle_select_cell(ds, event, (uint16_t)(frame - 0x18)))
      return 0;
